# React Error Boundary Component

## Implementation

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

// ─── Types ────────────────────────────────────────────────────────────────────

interface ErrorLog {
  message: string;
  stack?: string;
  componentStack?: string;
  timestamp: string;
  count: number;
}

interface Props {
  children: ReactNode;
  /** Custom fallback UI; receives error + retry fn */
  fallback?: (error: Error, retry: () => void) => ReactNode;
  /** Called whenever an error is caught */
  onError?: (error: Error, info: ErrorInfo) => void;
  /** Max retries before giving up (default: 3) */
  maxRetries?: number;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorLog: ErrorLog | null;
  retryCount: number;
}

// ─── Logger ───────────────────────────────────────────────────────────────────

const logError = (
  error: Error,
  info: ErrorInfo,
  count: number
): ErrorLog => {
  const log: ErrorLog = {
    message: error.message,
    stack: error.stack,
    componentStack: info.componentStack ?? undefined,
    timestamp: new Date().toISOString(),
    count,
  };

  // Console output with grouping for readability
  console.group(
    `%c⛔ React Error Boundary (occurrence #${count})`,
    "color:#e53e3e;font-weight:bold"
  );
  console.error("Error:", error.message);
  console.error("Stack trace:", error.stack);
  console.error("Component stack:", info.componentStack);
  console.info("Logged at:", log.timestamp);
  console.groupEnd();

  // ── Plug in your external error service here ──
  // Sentry.captureException(error, { extra: { componentStack: info.componentStack } });
  // datadogRum.addError(error, { source: "source", ...log });

  return log;
};

// ─── Error Boundary Class ─────────────────────────────────────────────────────

class ErrorBoundary extends Component<Props, State> {
  static defaultProps: Partial<Props> = {
    maxRetries: 3,
  };

  state: State = {
    hasError: false,
    error: null,
    errorLog: null,
    retryCount: 0,
  };

  // Render phase: derive state from thrown error
  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  // Commit phase: side-effects (logging, reporting)
  componentDidCatch(error: Error, info: ErrorInfo): void {
    const nextCount = this.state.retryCount + 1;

    const errorLog = logError(error, info, nextCount);
    this.setState({ errorLog });

    this.props.onError?.(error, info);
  }

  handleRetry = (): void => {
    const { maxRetries = 3 } = this.props;

    if (this.state.retryCount >= maxRetries) return;

    this.setState((prev) => ({
      hasError: false,
      error: null,
      errorLog: null,
      retryCount: prev.retryCount + 1,
    }));
  };

  handleReset = (): void => {
    this.setState({
      hasError: false,
      error: null,
      errorLog: null,
      retryCount: 0,
    });
  };

  render(): ReactNode {
    const { hasError, error, errorLog, retryCount } = this.state;
    const { children, fallback, maxRetries = 3 } = this.props;

    if (!hasError || !error) return children;

    // Consumer-supplied fallback
    if (fallback) return fallback(error, this.handleRetry);

    // Default fallback UI
    return (
      <DefaultFallback
        error={error}
        errorLog={errorLog}
        retryCount={retryCount}
        maxRetries={maxRetries}
        onRetry={this.handleRetry}
        onReset={this.handleReset}
      />
    );
  }
}

// ─── Default Fallback UI ──────────────────────────────────────────────────────

interface DefaultFallbackProps {
  error: Error;
  errorLog: ErrorLog | null;
  retryCount: number;
  maxRetries: number;
  onRetry: () => void;
  onReset: () => void;
}

const DefaultFallback: React.FC<DefaultFallbackProps> = ({
  error,
  errorLog,
  retryCount,
  maxRetries,
  onRetry,
  onReset,
}) => {
  const retriesLeft = maxRetries - retryCount;
  const isExhausted = retriesLeft <= 0;
  const [showDetails, setShowDetails] = React.useState(false);

  return (
    <div style={styles.overlay}>
      <div style={styles.card}>
        {/* ── Header ── */}
        <div style={styles.header}>
          <span style={styles.icon}>⛔</span>
          <h2 style={styles.title}>Something went wrong</h2>
        </div>

        {/* ── Message ── */}
        <p style={styles.message}>{error.message}</p>

        {/* ── Retry status ── */}
        {!isExhausted ? (
          <p style={styles.retryInfo}>
            {retriesLeft} retr{retriesLeft === 1 ? "y" : "ies"} remaining
          </p>
        ) : (
          <p style={styles.exhaustedInfo}>
            All retries exhausted. Please reload the page or contact support.
          </p>
        )}

        {/* ── Actions ── */}
        <div style={styles.actions}>
          {!isExhausted && (
            <button onClick={onRetry} style={styles.retryBtn}>
              🔄 Retry
            </button>
          )}
          <button onClick={onReset} style={styles.resetBtn}>
            ↩ Reset
          </button>
          <button
            onClick={() => window.location.reload()}
            style={styles.reloadBtn}
          >
            ⟳ Reload page
          </button>
        </div>

        {/* ── Collapsible error details ── */}
        <button
          onClick={() => setShowDetails((v) => !v)}
          style={styles.detailsToggle}
        >
          {showDetails ? "▲ Hide" : "▼ Show"} error details
        </button>

        {showDetails && errorLog && (
          <div style={styles.details}>
            <DetailRow label="Time" value={errorLog.timestamp} />
            <DetailRow label="Occurrences" value={String(errorLog.count)} />
            {errorLog.stack && (
              <pre style={styles.stack}>{errorLog.stack}</pre>
            )}
            {errorLog.componentStack && (
              <>
                <strong style={{ color: "#a0aec0" }}>Component stack</strong>
                <pre style={styles.stack}>{errorLog.componentStack}</pre>
              </>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

const DetailRow: React.FC<{ label: string; value: string }> = ({
  label,
  value,
}) => (
  <p style={{ margin: "4px 0", color: "#a0aec0", fontSize: 13 }}>
    <strong style={{ color: "#cbd5e0" }}>{label}:</strong> {value}
  </p>
);

// ─── Styles ───────────────────────────────────────────────────────────────────

const styles: Record<string, React.CSSProperties> = {
  overlay: {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    minHeight: "100vh",
    background: "#1a202c",
    padding: 16,
    fontFamily: "system-ui, sans-serif",
  },
  card: {
    background: "#2d3748",
    border: "1px solid #e53e3e",
    borderRadius: 12,
    padding: "32px 28px",
    maxWidth: 560,
    width: "100%",
    boxShadow: "0 4px 32px rgba(229,62,62,0.2)",
  },
  header: { display: "flex", alignItems: "center", gap: 12, marginBottom: 16 },
  icon: { fontSize: 28 },
  title: { margin: 0, color: "#fff", fontSize: 20, fontWeight: 700 },
  message: {
    background: "#1a202c",
    color: "#fc8181",
    borderRadius: 6,
    padding: "10px 14px",
    fontSize: 14,
    fontFamily: "monospace",
    wordBreak: "break-word",
    marginBottom: 12,
  },
  retryInfo: { color: "#68d391", fontSize: 13, margin: "0 0 16px" },
  exhaustedInfo: { color: "#fc8181", fontSize: 13, margin: "0 0 16px" },
  actions: { display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 16 },
  retryBtn: {
    padding: "9px 18px",
    background: "#3182ce",
    color: "#fff",
    border: "none",
    borderRadius: 6,
    cursor: "pointer",
    fontWeight: 600,
    fontSize: 14,
  },
  resetBtn: {
    padding: "9px 18px",
    background: "#2d3748",
    color: "#a0aec0",
    border: "1px solid #4a5568",
    borderRadius: 6,
    cursor: "pointer",
    fontWeight: 600,
    fontSize: 14,
  },
  reloadBtn: {
    padding: "9px 18px",
    background: "#744210",
    color: "#fefcbf",
    border: "none",
    borderRadius: 6,
    cursor: "pointer",
    fontWeight: 600,
    fontSize: 14,
  },
  detailsToggle: {
    background: "none",
    border: "none",
    color: "#63b3ed",
    cursor: "pointer",
    fontSize: 13,
    padding: 0,
    marginBottom: 8,
    textDecoration: "underline",
  },
  details: {
    background: "#1a202c",
    borderRadius: 6,
    padding: "12px 14px",
    marginTop: 8,
  },
  stack: {
    color: "#a0aec0",
    fontSize: 11,
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
    marginTop: 8,
    maxHeight: 180,
    overflowY: "auto",
  },
};

export default ErrorBoundary;
```

## Usage Examples

```tsx
// App.tsx

// ── 1. Basic usage ────────────────────────────────────────────────────────────
const App = () => (
  <ErrorBoundary maxRetries={3}>
    <MyComponent />
  </ErrorBoundary>
);

// ── 2. Custom error callback (e.g. Sentry) ────────────────────────────────────
const AppWithReporting = () => (
  <ErrorBoundary
    maxRetries={2}
    onError={(error, info) => {
      Sentry.captureException(error, {
        extra: { componentStack: info.componentStack },
      });
    }}
  >
    <Dashboard />
  </ErrorBoundary>
);

// ── 3. Fully custom fallback UI ───────────────────────────────────────────────
const AppWithCustomFallback = () => (
  <ErrorBoundary
    fallback={(error, retry) => (
      <div>
        <p>Custom UI: {error.message}</p>
        <button onClick={retry}>Try again</button>
      </div>
    )}
  >
    <FeatureWidget />
  </ErrorBoundary>
);

// ── 4. Nested boundaries for isolated sections ────────────────────────────────
const Dashboard = () => (
  <div>
    <ErrorBoundary maxRetries={1}>
      <Sidebar />
    </ErrorBoundary>

    <ErrorBoundary maxRetries={3}>
      <MainContent />
    </ErrorBoundary>
  </div>
);
```

## Test Component

```tsx
// BuggyCounter.tsx — use to verify the boundary works
import { useState } from "react";

const BuggyCounter = () => {
  const [count, setCount] = useState(0);

  if (count >= 3) throw new Error(`Simulated crash at count = ${count}`);

  return (
    <div style={{ padding: 24, textAlign: "center" }}>
      <p>Count: {count} — crashes at 3</p>
      <button onClick={() => setCount((c) => c + 1)}>Increment</button>
    </div>
  );
};

// Mount it inside an ErrorBoundary to test retry + logging
const TestPage = () => (
  <ErrorBoundary maxRetries={3} onError={console.error}>
    <BuggyCounter />
  </ErrorBoundary>
);
```

## Key Design Decisions

| Concern | Approach |
|---|---|
| **Error capture** | `getDerivedStateFromError` (render) + `componentDidCatch` (side-effects) |
| **Retry logic** | Resets state; hard cap via `maxRetries` prop |
| **Reset vs Retry** | *Retry* increments counter; *Reset* clears it entirely |
| **Logging** | Structured `ErrorLog` object with timestamps and occurrence count |
| **External services** | Stubbed comment hooks for Sentry / Datadog |
| **Custom fallback** | Render-prop pattern for full consumer control |
| **Nested boundaries** | Composable — wrap individual sections for fault isolation |
